#include <cmath>

double bezier(double x, double y, double& eqn, double P0[2], double P1[2],..., double Pn[2]) {
  eqn = 0.0;
  for (int i = 0; i <= n; i++) {
    double sum = 0.0;
    for (int j = 0; j <= n; j++) {
      if (i == j) continue;
      sum += P[j][0] * bezier_coefficients[i][j];
    }
    eqn += sum * P[i][0];
    eqn += P[i][1] * bezier_coefficients[i][n+1];
  }
  return eqn;
}

