import java.util.*;

public class MapFromListExample {
    public static void main(String[] args) {
        List<Person> people = Arrays.asList(
                new Person("John", "123 Main St", "New York"),
                new Person("Jane", "456 Elm St", "New York"),
                new Person("Bob", "789 Oak St", "Los Angeles")
        );

        Map<String, Person> map = people.stream()
                .collect(Collectors.toMap(Person::getFirstName, p -> p));

        System.out.println(map);
    }
}

class Person {
