Here's an example of a Scala object for encoding and decoding Base32 strings:

```
object Base32 {

  // The Base32 alphabet
  val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ" +
    "abcdefghijklmnopqrstuvwxyz" +
    "0123456789"

  // Encodes a given string into a Base32 string
  def encode(input: String): String = {
    var output = ""
    var i = 0
    while (i < input.length) {
      val char = input(i)
      val index = (char - 'A').toInt
      output += alphabet(index >> 3)
      if (index!= 0) output += alphabet(index % 32)
      i += 1
    }
    output
  }

  // Decodes a Base32 string into a UTF-8 encoded string
  def decode(input: String): String = {
    val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ" +
      "abcdefghijklmnopqrstuvwxyz" +
      "0123456789"
    var output = ""
    var i = 0
    while (i < input.length) {
      val char = input(i)
      if (char.isDigit) {
        val code = char - '0'
        output += alphabet(code >> 3)
        if (code!= 0) output += alphabet((code >> 6) & 0xF)
        i += 1
      } else {
        val index = alphabet.indexOf(char)
        if (index == -1) throw new IllegalArgumentException("Invalid Base32 character")
        output += index
        i += 1
      }
    }
    output
  }
}
```

