```python
import itertools

def draw_board(board):
    print(board)

def get_player_input(player):
    return input(f"{player}'s turn. Enter row and column separated by a space: ")

def make_move(board, row, col, player):
    if board[row][col] =='':
        board[row][col] = player
        draw_board(board)
        return True
    else:
        return False

def get_winner(board):
    for row in range(3):
        for col in range(3):
            if board[row][col] == '1':
                return 1
            elif board[row][col] == '2':
                return 2
    return 3

def play(game, player):
    while not game[0][0] in (2, 3) and not game[0][1] in (2, 3) and not game[0][2] in (2, 3):
        row = get_player_input(player)[0].split()[0]
        col = int(get_player_input(player)[-1])
        if make_move(game, row, col, player):
            game = get_winner(game)
            if game == 1:
                print(f"Player {player} wins!")
                break
            elif game == 2:
                print("It's a draw!")
                break
    else:
        print(f"The board is full. It's a draw!")

board = [[0 for _ in range(3)] for _ in range(3)]
play(board, 1)
```

