Here is an example VHDL program that generates a simple square wave using a D flip-flop:

library IEEE;
use IEEE.STD\_LOGIC\_1164.ALL;

entity square\_wave is
    Port ( clk : in  STD\_LOGIC;
           reset : in  STD\_LOGIC;
           square\_out : out  STD\_LOGIC);
end square\_wave;

architecture Behavioral of square\_wave is
    component D\_FF is
        Port ( D : in  STD\_LOGIC;
               clk : in  STD\_LOGIC;
               reset : in  STD\_LOGIC;
               Q : out  STD\_LOGIC);
    end component;

    signal Q : STD\_LOGIC;
begin
    U1: D\_FF port map (D => Q, clk => clk, reset => reset, Q => Q);
    square\_out <= Q;
end Behavioral;

program main is
    Port ( clk : in  STD\_LOGIC;
           reset : in  STD\_LOGIC;
           square\_out : out  STD\_LOGIC);
begin
    U2: square\_wave port map (clk => clk, reset => reset, square\_out => square\_out);
    wait for 10 ns;
    reset <= '1';
    wait for 10 ns;
    reset <= '0';
    wait for 10 ns;
end program main;

