Here is a simple image editor written in JavaScript:
```
// Get the image element
var img = document.getElementById("myImage");

// Create an object for the image properties
var imageProperties = {
  width: img.width,
  height: img.height,
  src: img.src,
  alt: img.alt
};

// Add a button to save the edited image
var saveButton = document.createElement("button");
saveButton.innerHTML = "Save";
saveButton.style.cssText = "position: absolute; left: 10px; top: 10px";

// Add an event listener to the button
saveButton.addEventListener("click", function() {
  // Create a new image element
  var newImg = document.createElement("img");
  newImg.src = imageProperties.src;
  newImg.style.cssText = "position: absolute; left: 10px; top: 10px";

  // Copy the properties of the original image to the new image
  newImg.width = imageProperties.width;
  newImg.height = imageProperties.height;
  newImg.style.width = imageProperties.width + "px";
  newImg.style.height = imageProperties.height + "px";

  // Add the edited image to the page
  document.body.appendChild(newImg);
});

// Add the button to the page
document.body.appendChild(saveButton);
```
This code creates a simple image editor that allows you to edit an image by changing its width and height. When you click the "Save" button, a new image element is created with the edited properties, and it is added to the page.

