// ==UserScript==
// @name        WebSocket Example
// @namespace    http://tampermonkey.net/
// @version      0.1
// @description  Example userscript to create a WebSocket connection to a specified URL.
// @author       You
// @match        https://example.com/*
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    // Define the WebSocket connection
    const ws = new WebSocket(`ws://${HOST}:${PORT}`);

    // Define the message to send when the WebSocket connection is opened
    ws.onopen = () => {
        ws.send(`Hello, WebSocket!`);
    };

    // Define the message to send when the WebSocket connection is closed
    ws.onclose = () => {
        console.log('WebSocket closed');
    };

    // Define the message to send when a message is received from the WebSocket server
    ws.onmessage = (event) => {
        console.log(`Received message: ${event.data}`);
    };

    // Define the message to send when an error occurs on the WebSocket connection
    ws.onerror = (event) => {
        console.log(`Error occurred: ${event.error}`);
    };
})();

